1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  body { font-family: system-ui, sans-serif; max-width: 32rem; margin: 2rem auto; padding: 0 1rem; color: #222; }
9	  h1 { font-size: 1.5rem; }
10	  form { display: flex; gap: .5rem; }
11	  form input { flex: 1; padding: .5rem; font-size: 1rem; }
12	  form input[type="date"] { flex: 0 0 auto; }
13	  button { padding: .5rem .75rem; font-size: 1rem; cursor: pointer; }
14	  ul { list-style: none; padding: 0; margin-top: 1rem; }
15	  li { display: flex; align-items: center; gap: .5rem; padding: .5rem 0; border-bottom: 1px solid #ddd; }
16	  li span { flex: 1; overflow-wrap: anywhere; }
17	  li[data-completed="true"] span { text-decoration: line-through; color: #888; }
18	  li time { font-size: .875rem; color: #555; white-space: nowrap; }
19	  li[data-overdue="true"] { background: #fdecea; }
20	  li[data-overdue="true"] time { color: #b00020; font-weight: 600; }
21	  .filters { display: flex; gap: .5rem; margin-top: 1rem; }
22	  .filters button[aria-pressed="true"] { font-weight: 600; }
23	</style>
24	</head>
25	<body>
26	<h1>Todos</h1>
27	<form id="add-form">
28	  <input data-testid="todo-input" type="text" placeholder="What needs doing?" autocomplete="off">
29	  <input data-testid="todo-due" type="date" aria-label="Due date">
30	  <select data-testid="todo-priority" aria-label="Priority">
31	    <option value="low">Low</option>
32	    <option value="med" selected>Med</option>
33	    <option value="high">High</option>
34	  </select>
35	  <button data-testid="todo-add" type="submit">Add</button>
36	</form>
37	<div class="filters">
38	  <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
39	  <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
40	  <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
41	</div>
42	<ul data-testid="todo-list"></ul>
43	<script>
44	(function () {
45	  var KEY = 'todos';
46	  var input = document.querySelector('[data-testid="todo-input"]');
47	  var dueInput = document.querySelector('[data-testid="todo-due"]');
48	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
49	  var list = document.querySelector('[data-testid="todo-list"]');
50	  var form = document.getElementById('add-form');
51	  var filterButtons = document.querySelectorAll('[data-filter]');
52	  var filter = 'all';
53	
54	  function load() {
55	    try {
56	      var data = JSON.parse(localStorage.getItem(KEY));
57	      return Array.isArray(data) ? data : [];
58	    } catch (e) {
59	      return [];
60	    }
61	  }
62	
63	  function save() {
64	    try { localStorage.setItem(KEY, JSON.stringify(todos)); } catch (e) {}
65	  }
66	
67	  function newId() {
68	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
69	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
70	  }
71	
72	  // Project rule: due dates are plain YYYY-MM-DD strings, read as LOCAL calendar dates.
73	  // Never parse them through Date/UTC. Overdue = due date strictly before today's local date.
74	  function validDue(value) {
75	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
76	  }
77	
78	  function pad(n) { return (n < 10 ? '0' : '') + n; }
79	
80	  function localToday(now) {
81	    return now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
82	  }
83	
84	  // Zero-padded YYYY-MM-DD strings sort lexicographically in date order.
85	  function isOverdue(due, today) {
86	    return !!validDue(due) && due < today;
87	  }
88	
89	  // Project rule: priority is low|med|high; anything else (including missing) is med.
90	  function validPriority(value) {
91	    return value === 'low' || value === 'high' ? value : 'med';
92	  }
93	
94	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
95	
96	  // Project rule: priority order high, med, low; insertion order within the same priority.
97	  // Stable sort keeps insertion order for ties.
98	  function byPriority(list) {
99	    return list
100	      .map(function (t, i) { return { t: t, i: i }; })
101	      .sort(function (a, b) {
102	        return (PRIORITY_RANK[validPriority(a.t.priority)] - PRIORITY_RANK[validPriority(b.t.priority)]) || (a.i - b.i);
103	      })
104	      .map(function (x) { return x.t; });
105	  }
106	
107	  // Project rule: active todos first, completed below; within each group, sorted by priority.
108	  function visibleTodos(all, f) {
109	    var active = byPriority(all.filter(function (t) { return !t.completed; }));
110	    var done = byPriority(all.filter(function (t) { return !!t.completed; }));
111	    if (f === 'active') return active;
112	    if (f === 'completed') return done;
113	    return active.concat(done);
114	  }
115	
116	  function render() {
117	    list.textContent = '';
118	    renderedDay = localToday(new Date());
119	    filterButtons.forEach(function (b) {
120	      b.setAttribute('aria-pressed', String(b.dataset.filter === filter));
121	    });
122	    visibleTodos(todos, filter).forEach(function (todo) {
123	      var li = document.createElement('li');
124	      li.setAttribute('data-testid', 'todo-item');
125	      li.setAttribute('data-completed', String(!!todo.completed));
126	      li.setAttribute('data-overdue', String(isOverdue(todo.due, renderedDay)));
127	      li.setAttribute('data-priority', validPriority(todo.priority));
128	      li.dataset.id = todo.id;
129	
130	      var toggle = document.createElement('input');
131	      toggle.setAttribute('data-testid', 'todo-toggle');
132	      toggle.type = 'checkbox';
133	      toggle.checked = !!todo.completed;
134	      toggle.setAttribute('aria-label', 'Mark complete');
135	      toggle.addEventListener('change', function () {
136	        todo.completed = toggle.checked;
137	        save();
138	        render();
139	      });
140	
141	      var text = document.createElement('span');
142	      text.setAttribute('data-testid', 'todo-text');
143	      text.textContent = todo.text;
144	
145	      var del = document.createElement('button');
146	      del.setAttribute('data-testid', 'todo-delete');
147	      del.type = 'button';
148	      del.textContent = 'Delete';
149	      del.addEventListener('click', function () {
150	        todos = todos.filter(function (t) { return t.id !== todo.id; });
151	        save();
152	        render();
153	      });
154	
155	      li.appendChild(toggle);
156	      li.appendChild(text);
157	      if (validDue(todo.due)) {
158	        var due = document.createElement('time');
159	        due.setAttribute('data-testid', 'todo-due-date');
160	        due.dateTime = todo.due;
161	        due.textContent = 'Due ' + todo.due;
162	        li.appendChild(due);
163	      }
164	      li.appendChild(del);
165	      list.appendChild(li);
166	    });
167	  }
168	
169	  var todos = load();
170	  var renderedDay = '';
171	
172	  form.addEventListener('submit', function (e) {
173	    e.preventDefault();
174	    var text = input.value.trim();
175	    if (!text) return;
176	    todos.push({ id: newId(), text: text, completed: false, createdAt: Date.now(), due: validDue(dueInput.value), priority: validPriority(priorityInput.value) });
177	    save();
178	    render();
179	    input.value = '';
180	    dueInput.value = '';
181	    priorityInput.value = 'med';
182	    input.focus();
183	  });
184	
185	  filterButtons.forEach(function (b) {
186	    b.addEventListener('click', function () {
187	      filter = b.dataset.filter;
188	      render();
189	    });
190	  });
191	
192	  // Re-render when the local calendar day changes so overdue flags stay current.
193	  setInterval(function () {
194	    if (localToday(new Date()) !== renderedDay) render();
195	  }, 60000);
196	
197	  render();
198	})();
199	</script>
200	</body>
201	</html>
